/* Sample-only sortie preparation. Uses the isolated Tactical foundation; no storage. */
(function(){'use strict';
const C=window.PROCore,T=window.PROTactical,$=id=>document.getElementById(id),el=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n;};
const sizes=C.UNIT_SIZES,domains=C.MOVEMENT_DOMAINS;
// Units and missions come from the Tactical pack (built-in sample for now).
const P=window.PROTacticalData,roster=P.roster();
const scenarios=Object.fromEntries(P.missions().map(m=>[m.id,{name:m.name,goal:m.goal,surface:m.surface}]));
let missionId='training-01',sequence=2,active='group-1',groups=[{id:'group-1',name:'第1部隊',faction:'player',mode:'auto',members:[]}],lastFocus;
const scenario=()=>scenarios[missionId],current=()=>groups.find(g=>g.id===active),occupied=id=>groups.find(g=>g.members.some(m=>m.uid===id));
function compatibility(u,g){if(u.move===undefined||!u.movementAptitude)return 'MOVE・地形移動適性が未設定';try{const m={uid:u.id,unit:u};T.defaultDomain(m,scenario().surface);if(g?.mode!=='auto'&&g?.mode&&!T.supports(m,g.mode))return domains[g.mode]+'に対応していません';}catch(e){return 'この戦場の移動領域に対応していません';}return '';}
function stats(g){return g.members.length?T.formation(g):{count:0,size:0,valid:false};}
function reason(u,g){const why=compatibility(u,g);if(why)return why;return T.joinReason(g.members.map(m=>m.unit),u);}
function setDomains(g){for(const m of g.members){try{m.domain=g.mode==='auto'?T.defaultDomain(m,scenario().surface):g.mode;}catch(e){delete m.domain;}}}
function tell(text){$('prepNotice').textContent=text;}
function button(text,fn,cls='secondary'){const b=el('button',cls,text);b.type='button';b.onclick=fn;return b;}
function redraw(){const s=scenario();$('prepMissionName').textContent=s.name;$('prepMissionInfo').textContent='勝利条件：'+s.goal+' ｜ 基準領域：'+domains[s.surface];$('prepRosterTarget').textContent=current().name+'に追加';
 const q=$('prepSearch').value.trim().toLocaleLowerCase();$('prepUnitList').replaceChildren();for(const u of roster.filter(u=>(u.name+' '+u.size).toLocaleLowerCase().includes(q))){const owner=occupied(u.id),r=owner?owner.name+'に編成済み':reason(u,current());const card=el('article','prep-unit'+(owner?' assigned':''));card.dataset.unit=u.id;const h=el('header');h.append(el('h3','',u.name),el('small','',u.size+' / サイズ'+sizes[u.size]+' / MOVE '+(u.move??'未設定')));const apt=el('div','aptitudes');for(const [key,label]of Object.entries(domains))apt.append(el('span','',label+' '+(u.movementAptitude?.[key]==='none'?'なし':u.movementAptitude?.[key]||'未設定')));card.append(h,apt,el('p','prep-help','武装：'+u.weapons.map(w=>w.name+'［'+w.minRange+'〜'+w.maxRange+'］').join('・')));if(r)card.append(el('p','prep-reason',r));const add=button(owner?'編成済み':r?'追加不可':'＋ '+current().name+'へ追加',()=>addUnit(u.id),'primary');add.disabled=!!r;add.dataset.add=u.id;card.append(add);$('prepUnitList').append(card);}
 $('prepGroups').replaceChildren();for(const g of groups){const f=stats(g),card=el('article','prep-group'+(g.id===active?' active':''));card.dataset.group=g.id;const top=el('div','prep-group-top');top.append(el('h3','',g.name),button(g.id===active?'追加先に選択中':'この部隊へ追加',()=>{active=g.id;tell(g.name+'を追加先に選択');redraw();}));card.append(top);const capacity=el('div','prep-capacity');for(const [label,value]of [['体数',f.count+' / '+T.SQUAD.count],['総サイズ',f.size+' / '+T.SQUAD.size],['部隊MOVE',g.members.length?String(T.groupMove(g)):'—']]){const box=el('div');box.append(el('span','',label),el('b','',value));capacity.append(box);}card.append(capacity);const bar=el('div','prep-sizebar'),fill=el('span');fill.style.width=(f.size/8*100)+'%';bar.append(fill);card.append(bar,el('p','prep-help','残りサイズ '+(8-f.size)+' ｜ 空き体数 '+(8-f.count)));
 const domainButton=button('移動状態：'+(g.mode==='auto'?'自動（個体ごと）':domains[g.mode])+' ▾',()=>chooseDomain(g),'prep-domain');domainButton.disabled=!g.members.length;card.append(domainButton);
 const used=[...new Set(g.members.map(m=>m.domain).filter(Boolean))];const basis=used.includes('ground')?'ground':used.includes('water')?'water':used.includes('underwater')?'underwater':used[0];let cost='—';if(g.members.length&&g.members.every(m=>m.domain)){try{cost=String(T.stepCost(g,Object.fromEntries(Object.keys(domains).map(k=>[k,1]))));}catch(e){}}
 card.append(el('p','prep-help','移動基準：'+(domains[basis]||'—')+' ｜ 個体の移動状態：'+(used.map(k=>domains[k]).join('・')||'—')+' ｜ 基本コスト1での消費：'+cost));

 const list=el('div','prep-members');if(!g.members.length)list.append(el('p','prep-empty','一覧からユニットを追加してください。'));for(const m of g.members){const row=el('div','prep-member'),text=el('div'),why=compatibility(m.unit,g);row.dataset.uid=m.uid;text.append(el('strong','',m.unit.name),el('small','',m.unit.size+' / サイズ'+sizes[m.unit.size]+' / '+(domains[m.domain]||'領域非対応')));if(why)text.append(el('small','prep-failed',why));const actions=el('div','actions');const move=button('移動',()=>chooseTransfer(g,m));move.disabled=groups.length<2;actions.append(move,button('外す',()=>removeUnit(g.id,m.uid)));row.append(text,actions);list.append(row);}card.append(list);
 if(!g.members.length&&groups.length>1)card.append(button('空の部隊を削除',()=>{groups=groups.filter(x=>x.id!==g.id);if(active===g.id)active=groups[0].id;redraw();}));$('prepGroups').append(card);}
 const nonempty=groups.filter(g=>g.members.length),errors=nonempty.flatMap(g=>g.members.filter(m=>compatibility(m.unit,g)).map(m=>g.name+'：'+m.unit.name+'が領域非対応'));$('prepSummary').textContent=nonempty.length+'部隊 / '+nonempty.reduce((n,g)=>n+g.members.length,0)+'体を編成'+(errors.length?' ｜ '+errors.join('、'):nonempty.length?' ｜ 出撃準備OK':' ｜ 最低1体を編成してください');$('prepConfirm').disabled=!nonempty.length||errors.length>0;}
function addUnit(id){const u=roster.find(u=>u.id===id),g=current();if(!u||occupied(id)||reason(u,g))return false;g.members.push({uid:id,unit:C.clone(u)});setDomains(g);tell(u.name+'を'+g.name+'に追加');redraw();return true;}
function removeUnit(gid,uid){const g=groups.find(g=>g.id===gid);g.members=g.members.filter(m=>m.uid!==uid);tell('ユニットを編成から外しました');redraw();}
function openChoice(title,choices){lastFocus=document.activeElement;$('prepChoiceTitle').textContent=title;const list=$('prepChoices');list.replaceChildren();for(const c of choices){const b=button(c.label,()=>{c.run();$('prepChoice').close();},'prep-choice');b.disabled=!!c.reason;if(c.current)b.setAttribute('aria-pressed','true');if(c.reason)b.append(el('small','',c.reason));list.append(b);}$('prepChoice').showModal();$('prepChoiceClose').focus();}
function chooseTransfer(g,m){openChoice(m.unit.name+'の移動先',groups.filter(x=>x.id!==g.id).map(target=>({label:target.name,reason:reason(m.unit,target),run:()=>{if(reason(m.unit,target))return;g.members=g.members.filter(x=>x.uid!==m.uid);target.members.push(m);setDomains(target);tell(m.unit.name+'を'+target.name+'へ移動');redraw();}})));}
function chooseDomain(g){const allowed=scenario().surface==='space'?['space']:scenario().surface==='water'?['water','underwater','air']:['ground','air'];openChoice(g.name+'の移動状態',[{label:'自動（各個体の適性を優先）',current:g.mode==='auto',run:()=>{g.mode='auto';setDomains(g);redraw();}},...allowed.map(domain=>({label:domains[domain],current:g.mode===domain,reason:T.canSwitch(g,domain)?'':'部隊の全個体が対応している必要があります',run:()=>{if(!T.canSwitch(g,domain))return;g.mode=domain;setDomains(g);tell(domains[domain]+'へ切替');redraw();}}))]);}
$('prepAddGroup').onclick=()=>{const id='group-'+sequence;groups.push({id,name:'第'+sequence+'部隊',faction:'player',mode:'auto',members:[]});sequence++;active=id;tell('新しい部隊を追加しました');redraw();const list=$('prepGroups');list.scrollTop=list.scrollHeight;};$('prepSearch').oninput=redraw;$('prepChoiceClose').onclick=()=>$('prepChoice').close();$('prepChoice').addEventListener('close',()=>{if(lastFocus?.isConnected)lastFocus.focus();});
$('prepConfirm').onclick=()=>{if($('prepConfirm').disabled)return;window.PROField.deploy(window.PROPreparation.snapshot());location.hash='#map';};
window.PROPreparation={setMission(id){if(!scenarios[id])return;if(missionId!==id){missionId=id;for(const g of groups){g.mode='auto';setDomains(g);}}tell('');redraw();},snapshot:()=>C.clone({missionId,active,groups}),addUnit};redraw();
})();
